BEGIN; -- ========================= -- 1) ANÚNCIO DE FRETE -- ========================= CREATE TABLE IF NOT EXISTS public.anuncio_frete ( id uuid NOT NULL DEFAULT gen_random_uuid(), empresa_id uuid NOT NULL, criado_por_usuario_id uuid NOT NULL, -- Step 1: Carga tipo_carga character varying(80) COLLATE pg_catalog."default" NOT NULL, descricao_adicional text COLLATE pg_catalog."default", peso_estimado_ton numeric(10,2) CHECK (peso_estimado_ton IS NULL OR peso_estimado_ton >= 0), -- Step 3: Valores e prazos valor_frete_centavos integer CHECK (valor_frete_centavos IS NULL OR valor_frete_centavos >= 0), previsao_entrega date, -- Qualificação / Regras do anúncio exige_motorista_verificado boolean NOT NULL DEFAULT true, score_minimo_motorista integer CHECK (score_minimo_motorista IS NULL OR score_minimo_motorista BETWEEN 0 AND 100), nivel_risco character varying(20) COLLATE pg_catalog."default", -- BAIXO / MEDIO / ALTO (segue teu padrão de texto) -- Status do fluxo status character varying(20) COLLATE pg_catalog."default" NOT NULL DEFAULT 'RASCUNHO'::character varying, publicado_em timestamp without time zone, expira_em timestamp without time zone, criado_em timestamp without time zone DEFAULT now(), atualizado_em timestamp without time zone DEFAULT now(), CONSTRAINT anuncio_frete_pkey PRIMARY KEY (id) ); -- FKs (padrão teu: NO ACTION / CASCADE) ALTER TABLE IF EXISTS public.anuncio_frete ADD CONSTRAINT fk_anuncio_frete_empresa FOREIGN KEY (empresa_id) REFERENCES public.empresa (id) MATCH SIMPLE ON UPDATE NO ACTION ON DELETE CASCADE; ALTER TABLE IF EXISTS public.anuncio_frete ADD CONSTRAINT fk_anuncio_frete_criado_por FOREIGN KEY (criado_por_usuario_id) REFERENCES public.usuario (id) MATCH SIMPLE ON UPDATE NO ACTION ON DELETE NO ACTION; CREATE INDEX IF NOT EXISTS idx_anuncio_frete_empresa_status ON public.anuncio_frete(empresa_id, status); CREATE INDEX IF NOT EXISTS idx_anuncio_frete_status_publicado ON public.anuncio_frete(status, publicado_em DESC); -- ========================= -- 2) ROTA DO ANÚNCIO (origem/destino) -- ========================= CREATE TABLE IF NOT EXISTS public.anuncio_frete_rota ( id uuid NOT NULL DEFAULT gen_random_uuid(), anuncio_frete_id uuid NOT NULL, origem_cidade character varying(100) COLLATE pg_catalog."default" NOT NULL, origem_uf character varying(2) COLLATE pg_catalog."default" NOT NULL, destino_cidade character varying(100) COLLATE pg_catalog."default" NOT NULL, destino_uf character varying(2) COLLATE pg_catalog."default" NOT NULL, origem_lat numeric(10,6), origem_lng numeric(10,6), destino_lat numeric(10,6), destino_lng numeric(10,6), criado_em timestamp without time zone DEFAULT now(), atualizado_em timestamp without time zone DEFAULT now(), CONSTRAINT anuncio_frete_rota_pkey PRIMARY KEY (id), CONSTRAINT anuncio_frete_rota_anuncio_unique UNIQUE (anuncio_frete_id) ); ALTER TABLE IF EXISTS public.anuncio_frete_rota ADD CONSTRAINT fk_anuncio_frete_rota_anuncio FOREIGN KEY (anuncio_frete_id) REFERENCES public.anuncio_frete (id) MATCH SIMPLE ON UPDATE NO ACTION ON DELETE CASCADE; CREATE INDEX IF NOT EXISTS idx_anuncio_frete_rota_origem ON public.anuncio_frete_rota(origem_uf, origem_cidade); CREATE INDEX IF NOT EXISTS idx_anuncio_frete_rota_destino ON public.anuncio_frete_rota(destino_uf, destino_cidade); -- ========================= -- 3) PONTOS DA ROTA (opcional) -- Ex: múltiplas entregas/paradas -- ========================= CREATE TABLE IF NOT EXISTS public.anuncio_frete_rota_pontos ( id uuid NOT NULL DEFAULT gen_random_uuid(), anuncio_frete_id uuid NOT NULL, ordem integer NOT NULL, cliente_destinatario character varying(150) COLLATE pg_catalog."default", local_entrega character varying(200) COLLATE pg_catalog."default", ponto_encontro character varying(200) COLLATE pg_catalog."default", link_local text COLLATE pg_catalog."default", entrega_lat numeric(10,6), entrega_lng numeric(10,6), status character varying(20) COLLATE pg_catalog."default" NOT NULL DEFAULT 'PENDENTE'::character varying, criado_em timestamp without time zone DEFAULT now(), atualizado_em timestamp without time zone DEFAULT now(), CONSTRAINT anuncio_frete_rota_pontos_pkey PRIMARY KEY (id), CONSTRAINT anuncio_frete_rota_pontos_unique UNIQUE (anuncio_frete_id, ordem) ); ALTER TABLE IF EXISTS public.anuncio_frete_rota_pontos ADD CONSTRAINT fk_anuncio_frete_rota_pontos_anuncio FOREIGN KEY (anuncio_frete_id) REFERENCES public.anuncio_frete (id) MATCH SIMPLE ON UPDATE NO ACTION ON DELETE CASCADE; CREATE INDEX IF NOT EXISTS idx_anuncio_rota_pontos_anuncio ON public.anuncio_frete_rota_pontos(anuncio_frete_id, ordem); -- ========================= -- 4) CONTATO DO ANÚNCIO -- ========================= CREATE TABLE IF NOT EXISTS public.anuncio_frete_contato ( id uuid NOT NULL DEFAULT gen_random_uuid(), anuncio_frete_id uuid NOT NULL UNIQUE, telefone_whatsapp character varying(30) COLLATE pg_catalog."default", email_operacional character varying(120) COLLATE pg_catalog."default", criado_em timestamp without time zone DEFAULT now(), atualizado_em timestamp without time zone DEFAULT now(), CONSTRAINT anuncio_frete_contato_pkey PRIMARY KEY (id) ); ALTER TABLE IF EXISTS public.anuncio_frete_contato ADD CONSTRAINT fk_anuncio_frete_contato_anuncio FOREIGN KEY (anuncio_frete_id) REFERENCES public.anuncio_frete (id) MATCH SIMPLE ON UPDATE NO ACTION ON DELETE CASCADE; -- ========================= -- 5) PROPOSTAS (motoristas) -- ========================= CREATE TABLE IF NOT EXISTS public.anuncio_frete_propostas ( id uuid NOT NULL DEFAULT gen_random_uuid(), anuncio_frete_id uuid NOT NULL, motorista_id uuid NOT NULL, valor_proposto_centavos integer NOT NULL CHECK (valor_proposto_centavos >= 0), mensagem text COLLATE pg_catalog."default", status character varying(20) COLLATE pg_catalog."default" NOT NULL DEFAULT 'ENVIADA'::character varying, -- ENVIADA / CONTRAPROPOSTA / ACEITA / RECUSADA / CANCELADA criado_em timestamp without time zone DEFAULT now(), atualizado_em timestamp without time zone DEFAULT now(), CONSTRAINT anuncio_frete_propostas_pkey PRIMARY KEY (id) ); ALTER TABLE IF EXISTS public.anuncio_frete_propostas ADD CONSTRAINT fk_anuncio_frete_propostas_anuncio FOREIGN KEY (anuncio_frete_id) REFERENCES public.anuncio_frete (id) MATCH SIMPLE ON UPDATE NO ACTION ON DELETE CASCADE; ALTER TABLE IF EXISTS public.anuncio_frete_propostas ADD CONSTRAINT fk_anuncio_frete_propostas_motorista FOREIGN KEY (motorista_id) REFERENCES public.motorista (id) MATCH SIMPLE ON UPDATE NO ACTION ON DELETE CASCADE; CREATE INDEX IF NOT EXISTS idx_anuncio_frete_propostas_anuncio_status ON public.anuncio_frete_propostas(anuncio_frete_id, status); CREATE INDEX IF NOT EXISTS idx_anuncio_frete_propostas_motorista ON public.anuncio_frete_propostas(motorista_id, criado_em DESC); -- ========================= -- 6) VISUALIZAÇÕES (log) -- ========================= CREATE TABLE IF NOT EXISTS public.anuncio_frete_visualizacoes ( id uuid NOT NULL DEFAULT gen_random_uuid(), anuncio_frete_id uuid NOT NULL, usuario_id uuid, motorista_id uuid, ip_hash character varying(64) COLLATE pg_catalog."default", user_agent text COLLATE pg_catalog."default", criado_em timestamp without time zone DEFAULT now(), CONSTRAINT anuncio_frete_visualizacoes_pkey PRIMARY KEY (id) ); ALTER TABLE IF EXISTS public.anuncio_frete_visualizacoes ADD CONSTRAINT fk_anuncio_frete_visualizacoes_anuncio FOREIGN KEY (anuncio_frete_id) REFERENCES public.anuncio_frete (id) MATCH SIMPLE ON UPDATE NO ACTION ON DELETE CASCADE; ALTER TABLE IF EXISTS public.anuncio_frete_visualizacoes ADD CONSTRAINT fk_anuncio_frete_visualizacoes_usuario FOREIGN KEY (usuario_id) REFERENCES public.usuario (id) MATCH SIMPLE ON UPDATE NO ACTION ON DELETE SET NULL; ALTER TABLE IF EXISTS public.anuncio_frete_visualizacoes ADD CONSTRAINT fk_anuncio_frete_visualizacoes_motorista FOREIGN KEY (motorista_id) REFERENCES public.motorista (id) MATCH SIMPLE ON UPDATE NO ACTION ON DELETE SET NULL; CREATE INDEX IF NOT EXISTS idx_anuncio_frete_visualizacoes_anuncio ON public.anuncio_frete_visualizacoes(anuncio_frete_id, criado_em DESC); -- ========================= -- 7) MÉTRICAS AGREGADAS (pra dashboard) -- ========================= CREATE TABLE IF NOT EXISTS public.anuncio_frete_metricas ( anuncio_frete_id uuid NOT NULL, visualizacoes integer NOT NULL DEFAULT 0, propostas integer NOT NULL DEFAULT 0, atualizado_em timestamp without time zone DEFAULT now(), CONSTRAINT anuncio_frete_metricas_pkey PRIMARY KEY (anuncio_frete_id) ); ALTER TABLE IF EXISTS public.anuncio_frete_metricas ADD CONSTRAINT fk_anuncio_frete_metricas_anuncio FOREIGN KEY (anuncio_frete_id) REFERENCES public.anuncio_frete (id) MATCH SIMPLE ON UPDATE NO ACTION ON DELETE CASCADE; END;